    title: 'Глютен и лактоза: кому действительно нужно их избегать?',
    preview: 'Глютен: что это и почему он стал проблемой для многих?',
    image: 'https://s3.firstvds.ru/articles/aoqi29vjazsdjfjsa8oc6icexlg5h3ym.jpg',
